<?php
 namespace Pterodactyl\Services\Dezerx\Importer; use Closure; trait RemoteWalk { private const NEVER = ['.ssh', '.bash_history', '.profile', '.bashrc']; private const PROGRESS_EVERY_SECONDS = 1.0; public function walk(string $root, int $maxFiles, int $maxBytes, ?Closure $onProgress = null): array { $files = []; $bytes = 0; $queue = ['']; $truncated = false; $lastReport = microtime(true); while ($queue !== [] && !$truncated) { $relative = array_shift($queue); $entries = $this->listing(rtrim($root . '/' . $relative, '/')); if ($entries === null) { continue; } foreach ($entries as $entry) { $name = $entry['name']; if (in_array($name, self::NEVER, true)) { continue; } $path = $relative === '' ? $name : $relative . '/' . $name; if ($entry['directory']) { $queue[] = $path; continue; } $files[$path] = $entry['size']; $bytes += $entry['size']; if ($onProgress !== null && microtime(true) - $lastReport >= self::PROGRESS_EVERY_SECONDS) { $onProgress(count($files), $bytes); $lastReport = microtime(true); } if (($maxFiles > 0 && count($files) > $maxFiles) || ($maxBytes > 0 && $bytes > $maxBytes)) { $truncated = true; break; } } } return ['files' => $files, 'bytes' => $bytes, 'truncated' => $truncated]; } } 